   143→- [ ] **Step 3: Create store.ts**
   144→
   145→```typescript
   146→// packages/core/src/account/ops/store.ts
   147→
   148→import { writeFile, chmod } from "node:fs/promises";
   149→import { existsSync } from "node:fs";
   150→import { dirname, join } from "node:path";
   151→import { readYaml, writeYaml } from "../../config/yaml";
   152→import { getAccountsPath } from "../../config/paths";
   153→import type { AccountRecord } from "./types";
   154→
   155→interface AccountsFile {
   156→  accounts: AccountRecord[];
   157→}
   158→
   159→export function getAccountsFilePath(): string {
   160→  return getAccountsPath();
   161→}
   162→
   163→export async function readAccounts(): Promise<AccountRecord[]> {
   164→  const filePath = getAccountsFilePath();
   165→  if (!existsSync(filePath)) return [];
   166→  const data = await readYaml<AccountsFile>(filePath);
   167→  return data?.accounts ?? [];
   168→}
   169→
   170→export async function writeAccounts(accounts: AccountRecord[]): Promise<void> {
   171→  const filePath = getAccountsFilePath();
   172→  // Atomic write: writeYaml creates parent dirs if needed
   173→  await writeYaml(filePath, { accounts });
   174→  // Set file permissions to 0600 (owner read/write only)
   175→  await chmod(filePath, 0o600);
   176→}
   177→
   178→export function maskCredential(value: string): string {
   179→  if (value.length <= 4) return "****";
   180→  return "****" + value.slice(-4);
   181→}
   182→```
