   258→- [ ] **Step 2: Create OKX adapter**
   259→
   260→```typescript
   261→// packages/core/src/account/ops/exchanges/okx.ts
   262→
   263→import { createHmac } from "node:crypto";
   264→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
   265→import type { TestResult } from "../types";
   266→
   267→const BASE_URL = "https://www.okx.com";
   268→
   269→export const okxExchange: Exchange = {
   270→  id: "okx",
   271→  name: "OKX",
   272→  fields: ["api_key", "secret", "passphrase"],
   273→  referral_url: "https://okx.com/join/80926498",
   274→  api_doc_url: "https://www.okx.com/account/my-api",
   275→
   276→  sign(credentials: Credentials, params: SignParams): SignedRequest {
   277→    const { method, path, body } = params;
   278→    const timestamp = params.timestamp;
   279→    const prehash = timestamp + method + path + (body ?? "");
   280→    const signature = createHmac("sha256", credentials.secret)
   281→      .update(prehash)
   282→      .digest("base64");
   283→
   284→    return {
   285→      url: BASE_URL + path,
   286→      headers: {
   287→        "OK-ACCESS-KEY": credentials.api_key,
   288→        "OK-ACCESS-SIGN": signature,
   289→        "OK-ACCESS-TIMESTAMP": timestamp,
   290→        "OK-ACCESS-PASSPHRASE": credentials.passphrase ?? "",
   291→        "Content-Type": "application/json",
   292→      },
   293→    };
   294→  },
   295→
   296→  async testConnection(credentials: Credentials): Promise<TestResult> {
   297→    const timestamp = new Date().toISOString();
   298→    const path = "/api/v5/account/balance";
   299→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
   300→
   301→    const start = Date.now();
   302→    try {
   303→      const res = await fetch(signed.url, {
   304→        method: "GET",
   305→        headers: signed.headers,
   306→        signal: AbortSignal.timeout(10_000),
   307→      });
   308→      const latency_ms = Date.now() - start;
   309→      const json = (await res.json()) as { code?: string; msg?: string };
   310→
   311→      if (json.code === "0") {
   312→        return { success: true, latency_ms };
   313→      }
   314→      return { success: false, error: json.msg ?? `Error code: ${json.code}`, latency_ms };
   315→    } catch (e) {
   316→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
   317→    }
   318→  },
   319→};
   320→```
