   388→- [ ] **Step 1: Create Binance adapter**
   389→
   390→```typescript
   391→// packages/core/src/account/ops/exchanges/binance.ts
   392→
   393→import { createHmac } from "node:crypto";
   394→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
   395→import type { TestResult } from "../types";
   396→
   397→const BASE_URL = "https://api.binance.com";
   398→
   399→export const binanceExchange: Exchange = {
   400→  id: "binance",
   401→  name: "Binance",
   402→  fields: ["api_key", "secret"],
   403→  referral_url: "https://accounts.binance.com/register?ref=11427183",
   404→  api_doc_url: "https://www.binance.com/en/my/settings/api-management",
   405→  whitelist_ip: "195.135.193.235",
   406→
   407→  sign(credentials: Credentials, params: SignParams): SignedRequest {
   408→    const { method, path } = params;
   409→    const queryString = params.params
   410→      ? Object.entries(params.params).map(([k, v]) => `${k}=${v}`).join("&")
   411→      : "";
   412→    const toSign = queryString + (queryString ? "&" : "") + `timestamp=${params.timestamp}`;
   413→    const signature = createHmac("sha256", credentials.secret)
   414→      .update(toSign)
   415→      .digest("hex");
   416→    const fullQuery = toSign + `&signature=${signature}`;
   417→
   418→    return {
   419→      url: `${BASE_URL}${path}?${fullQuery}`,
   420→      headers: {
   421→        "X-MBX-APIKEY": credentials.api_key,
   422→      },
   423→    };
   424→  },
   425→
   426→  async testConnection(credentials: Credentials): Promise<TestResult> {
   427→    const timestamp = Date.now().toString();
   428→    const path = "/api/v3/account";
   429→    const signed = this.sign(credentials, { method: "GET", path, timestamp });
   430→
   431→    const start = Date.now();
   432→    try {
   433→      const res = await fetch(signed.url, {
   434→        method: "GET",
   435→        headers: signed.headers,
   436→        signal: AbortSignal.timeout(10_000),
   437→      });
   438→      const latency_ms = Date.now() - start;
   439→
   440→      if (res.ok) return { success: true, latency_ms };
   441→      const json = (await res.json()) as { msg?: string; code?: number };
   442→      return { success: false, error: json.msg ?? `HTTP ${res.status}`, latency_ms };
   443→    } catch (e) {
   444→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
   445→    }
   446→  },
   447→};
   448→```
