  1738→      const res = await fetch(`${GATEWAY}/api/accounts/${id}`, { method: "DELETE" });
  1739→      const data = await res.json();
  1740→      if (data.success) {
  1741→        toast.success("账户已删除");
  1742→        await fetchData();
  1743→      } else {
  1744→        toast.error(data.error ?? "删除失败");
  1745→      }
  1746→    } catch {
  1747→      toast.error("网络错误");
  1748→    }
  1749→  };
  1750→
  1751→  return (
  1752→    <Dialog open={open} onOpenChange={onOpenChange}>
  1753→      <DialogContent className="max-w-4xl h-[70vh] p-0 gap-0 overflow-hidden">
  1754→        <DialogHeader className="px-6 py-4 border-b">
  1755→          <DialogTitle>导入交易账户</DialogTitle>
  1756→        </DialogHeader>
  1757→
  1758→        <div className="flex flex-1 overflow-hidden">
  1759→          {/* Left panel — exchange list */}
  1760→          <ScrollArea className="w-56 border-r">
  1761→            <div className="p-2">
  1762→              {exchanges.map((ex) => {
  1763→                const count = accounts.filter((a) => a.exchange === ex.id).length;
  1764→                return (
  1765→                  <button
  1766→                    key={ex.id}
  1767→                    onClick={() => handleSelectExchange(ex.id)}
  1768→                    className={cn(
  1769→                      "w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm",
  1770→                      selectedExchange === ex.id
  1771→                        ? "bg-accent text-accent-foreground"
  1772→                        : "hover:bg-muted"
  1773→                    )}
  1774→                  >
  1775→                    <span className="font-medium">{ex.name}</span>
  1776→                    {count > 0 && <Badge variant="secondary" className="text-xs">{count}</Badge>}
  1777→                  </button>
  1778→                );
  1779→              })}
  1780→            </div>
  1781→          </ScrollArea>
  1782→
  1783→          {/* Right panel — form / account list */}
  1784→          <div className="flex-1 overflow-y-auto p-6">
  1785→            {currentExchange && (
  1786→              <>
  1787→                {/* Top links */}
  1788→                <div className="flex gap-2 mb-4">
  1789→                  {currentExchange.referral_url && (
  1790→                    <Button variant="outline" size="sm" asChild>
  1791→                      <a href={currentExchange.referral_url} target="_blank" rel="noreferrer">
  1792→                        注册(手续费折扣) <ExternalLink className="ml-1 h-3 w-3" />
  1793→                      </a>
  1794→                    </Button>
  1795→                  )}
  1796→                  {currentExchange.api_doc_url && (
  1797→                    <Button variant="outline" size="sm" asChild>
  1798→                      <a href={currentExchange.api_doc_url} target="_blank" rel="noreferrer">
  1799→                        创建API <ExternalLink className="ml-1 h-3 w-3" />
  1800→                      </a>
  1801→                    </Button>
  1802→                  )}
  1803→                </div>
  1804→
  1805→                {/* Whitelist IP (Binance) */}
  1806→                {currentExchange.whitelist_ip && (
  1807→                  <div className="mb-4 p-3 rounded-lg border bg-muted/50 flex items-center justify-between">
  1808→                    <span className="text-sm">白名单IP: <code>{currentExchange.whitelist_ip}</code></span>
  1809→                    <Button
  1810→                      variant="ghost"
  1811→                      size="sm"
  1812→                      onClick={() => {
  1813→                        navigator.clipboard.writeText(currentExchange.whitelist_ip!);
  1814→                        toast.success("IP已复制");
  1815→                      }}
  1816→                    >
  1817→                      <Copy className="h-3 w-3" />
  1818→                    </Button>
  1819→                  </div>
  1820→                )}
  1821→
  1822→                {/* Existing accounts */}
  1823→                {exchangeAccounts.length > 0 && !showForm && (
  1824→                  <div className="space-y-2 mb-4">
  1825→                    {exchangeAccounts.map((acc) => (
  1826→                      <div key={acc.id} className="flex items-center justify-between p-3 rounded-lg border">
  1827→                        <div>
  1828→                          <p className="text-sm font-medium">{acc.name}</p>
  1829→                          <p className="text-xs text-muted-foreground">{new Date(acc.created_at).toLocaleDateString()}</p>
  1830→                        </div>
  1831→                        <div className="flex gap-1">
  1832→                          <Button variant="ghost" size="sm" onClick={() => handleTest(acc.id)}>
  1833→                            <Zap className="h-3 w-3" />
  1834→                          </Button>
  1835→                          <Button variant="ghost" size="sm" onClick={() => handleDelete(acc.id)}>
  1836→                            <Trash2 className="h-3 w-3" />
  1837→                          </Button>
  1838→                        </div>
  1839→                      </div>
  1840→                    ))}
  1841→                  </div>
  1842→                )}
  1843→
  1844→                {/* Add new / Form */}
  1845→                {!showForm ? (
  1846→                  <Button variant="outline" onClick={handleAddNew}>+ 添加新账户</Button>
  1847→                ) : (
  1848→                  <div className="space-y-4">
  1849→                    <div>
  1850→                      <label className="text-sm font-medium">账户名称</label>
  1851→                      <Input value={formName} onChange={(e) => setFormName(e.target.value)} className="mt-1" />
  1852→                    </div>
  1853→
  1854→                    <div>
  1855→                      <label className="text-sm font-medium">API密钥 *</label>
  1856→                      <div className="relative mt-1">
  1857→                        <Input
  1858→                          type={showApiKey ? "text" : "password"}
  1859→                          value={formApiKey}
  1860→                          onChange={(e) => setFormApiKey(e.target.value)}
  1861→                          placeholder="请输入API密钥"
  1862→                        />
  1863→                        <button
  1864→                          type="button"
  1865→                          className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground"
  1866→                          onClick={() => setShowApiKey(!showApiKey)}
  1867→                        >
  1868→                          {showApiKey ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
  1869→                        </button>
  1870→                      </div>
  1871→                      <p className="text-xs text-muted-foreground mt-1">API Key 将被存储，请确保其有效</p>
  1872→                    </div>
  1873→
  1874→                    <div>
  1875→                      <label className="text-sm font-medium">密钥 *</label>
  1876→                      <div className="relative mt-1">
  1877→                        <Input
  1878→                          type={showSecret ? "text" : "password"}
  1879→                          value={formSecret}
  1880→                          onChange={(e) => setFormSecret(e.target.value)}
  1881→                          placeholder="输入密钥"
  1882→                        />
  1883→                        <button
  1884→                          type="button"
  1885→                          className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground"
  1886→                          onClick={() => setShowSecret(!showSecret)}
  1887→                        >
  1888→                          {showSecret ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
  1889→                        </button>
  1890→                      </div>
  1891→                    </div>
  1892→
  1893→                    {currentExchange.fields.includes("passphrase") && (
  1894→                      <div>
  1895→                        <label className="text-sm font-medium">密码(Passphrase) *</label>
  1896→                        <Input
  1897→                          type="password"
  1898→                          value={formPassphrase}
  1899→                          onChange={(e) => setFormPassphrase(e.target.value)}
  1900→                          placeholder="输入密码(Passphrase)"
  1901→                          className="mt-1"
  1902→                        />
  1903→                      </div>
  1904→                    )}
  1905→
  1906→                    <div className="flex justify-end gap-2 pt-2">
  1907→                      <Button variant="outline" onClick={() => setShowForm(false)}>取消</Button>
  1908→                      <Button onClick={handleSave} disabled={saving}>
  1909→                        {saving ? "保存中..." : "保存配置"}
  1910→                      </Button>
  1911→                    </div>
  1912→                  </div>
  1913→                )}
  1914→              </>
  1915→            )}
  1916→          </div>
  1917→        </div>
  1918→      </DialogContent>
  1919→    </Dialog>
  1920→  );
  1921→}
  1922→```
